To accomplish your task, you can write a Go program that reads all the Go files in a directory, parses them to find all types that implement the `FileError` interface (by checking if they have the `IsFileError()` method), and then generates code to handle these types in your `UnmarshalJSON` function.

Here's a step-by-step guide and code example:

1. **Read Go Files from Directory**: Use `filepath.Walk` to traverse the directory and collect all `.go` files.

2. **Parse Go Files**: Use `go/parser` and `go/ast` packages to parse each Go file and construct the Abstract Syntax Tree (AST).

3. **Collect Types and Methods**:
   - Walk through the AST nodes to find all type declarations (`*ast.TypeSpec`).
   - Collect methods (`*ast.FuncDecl`) and associate them with their receiver types.
   - Build a map from type names to their methods.

4. **Identify Types Implementing `FileError` Interface**:
   - For each type, check if it has a method named `IsFileError`. These types are considered to implement the `FileError` interface.

5. **Generate Code for `UnmarshalJSON` Function**:
   - For each identified type, generate code similar to your example, handling the unmarshalling logic for that type.
   - This code can be dynamically generated as a string and written to a file or incorporated into your existing codebase.

Here's the complete code to achieve this:

```go
package main

import (
    "fmt"
    "go/parser"
    "go/token"
    "go/ast"
    "io/ioutil"
    "os"
    "path/filepath"
    "strings"
)

type TypeInfo struct {
    Name    string
    Methods map[string]bool
}

func getGoFiles(root string) ([]string, error) {
    var files []string
    err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
        if err != nil {
            return err
        }
        if !info.IsDir() && strings.HasSuffix(path, ".go") {
            files = append(files, path)
        }
        return nil
    })
    return files, err
}

func collectTypesAndMethods(files []string) (map[string]*TypeInfo, error) {
    typeInfos := make(map[string]*TypeInfo)
    for _, file := range files {
        fset := token.NewFileSet()
        src, err := ioutil.ReadFile(file)
        if err != nil {
            return nil, err
        }
        parsedFile, err := parser.ParseFile(fset, file, src, 0)
        if err != nil {
            return nil, err
        }
        // Initialize map to store methods by type name
        ast.Inspect(parsedFile, func(n ast.Node) bool {
            switch x := n.(type) {
            case *ast.TypeSpec:
                typeName := x.Name.Name
                if _, exists := typeInfos[typeName]; !exists {
                    typeInfos[typeName] = &TypeInfo{
                        Name:    typeName,
                        Methods: make(map[string]bool),
                    }
                }
            case *ast.FuncDecl:
                if x.Recv != nil && len(x.Recv.List) > 0 {
                    // Get receiver type
                    var typeName string
                    switch recvType := x.Recv.List[0].Type.(type) {
                    case *ast.StarExpr:
                        // Pointer receiver
                        if ident, ok := recvType.X.(*ast.Ident); ok {
                            typeName = ident.Name
                        }
                    case *ast.Ident:
                        // Value receiver
                        typeName = recvType.Name
                    }
                    methodName := x.Name.Name
                    if typeName != "" {
                        if _, exists := typeInfos[typeName]; !exists {
                            typeInfos[typeName] = &TypeInfo{
                                Name:    typeName,
                                Methods: make(map[string]bool),
                            }
                        }
                        typeInfos[typeName].Methods[methodName] = true
                    }
                }
            }
            return true
        })
    }
    return typeInfos, nil
}

func main() {
    // Replace "your/directory/path" with the path to the directory containing your Go files
    goFiles, err := getGoFiles("your/directory/path")
    if err != nil {
        fmt.Printf("Error reading Go files: %v\n", err)
        return
    }

    typeInfos, err := collectTypesAndMethods(goFiles)
    if err != nil {
        fmt.Printf("Error collecting types and methods: %v\n", err)
        return
    }

    // Identify types implementing FileError interface
    var fileErrorTypes []string
    for _, info := range typeInfos {
        if _, exists := info.Methods["IsFileError"]; exists {
            fileErrorTypes = append(fileErrorTypes, info.Name)
        }
    }

    // Generate code for UnmarshalJSON function
    fmt.Println("func (e *StoreType) UnmarshalJSON(bytes []byte) error {")
    fmt.Println("    localType := struct {")
    fmt.Println("        Type string `json:\"type\"`")
    fmt.Println("        Err json.RawMessage `json:\"error\"`")
    fmt.Println("    }{}")
    fmt.Println("    if err := json.Unmarshal(bytes, &localType); err != nil {")
    fmt.Println("        return err")
    fmt.Println("    }")
    fmt.Println("    switch localType.Type {")
    for _, typeName := range fileErrorTypes {
        fmt.Printf("    case reflect.TypeOf(&%s{}).String():\n", typeName)
        fmt.Printf("        var te %s\n", typeName)
        fmt.Println("        if unmarshallError := json.Unmarshal(localType.Err, &te); unmarshallError != nil {")
        fmt.Println("            return unmarshallError")
        fmt.Println("        }")
        fmt.Println("        e.Err = &te")
        fmt.Println("        e.Type = localType.Type")
    }
    fmt.Println("    default:")
    fmt.Println("        return &UnknownStoreTypeError{TypeName: localType.Type}")
    fmt.Println("    }")
    fmt.Println("    return nil")
    fmt.Println("}")
}
```

**Explanation:**

- **getGoFiles**: Reads all Go files in the specified directory.
- **collectTypesAndMethods**: Parses each Go file and collects type information and their methods.
- **main**: Orchestrates the process, identifies types implementing `FileError`, and generates the `UnmarshalJSON` function code.

**Note**: Replace `"your/directory/path"` with the path to your directory containing the Go files.

