func collectTypesAndMethods(files []string) (map[string]*TypeInfo, error) {
    typeInfos := make(map[string]*TypeInfo)
    for _, file := range files {
        fset := token.NewFileSet()
        src, err := ioutil.ReadFile(file)
        if err != nil {
            return nil, err
        }
        parsedFile, err := parser.ParseFile(fset, file, src, parser.AllErrors)
        if err != nil {
            return nil, err
        }
        // Traverse the AST to collect types and their methods
        ast.Inspect(parsedFile, func(n ast.Node) bool {
            switch x := n.(type) {
            case *ast.TypeSpec:
                typeName := x.Name.Name
                if _, exists := typeInfos[typeName]; !exists {
                    typeInfos[typeName] = &TypeInfo{
                        Name:    typeName,
                        Methods: make(map[string]*MethodInfo),
                    }
                }
            case *ast.FuncDecl:
                if x.Recv != nil && len(x.Recv.List) > 0 {
                    // Get receiver type
                    var typeName string
                    switch recvType := x.Recv.List[0].Type.(type) {
                    case *ast.StarExpr:
                        // Pointer receiver
                        if ident, ok := recvType.X.(*ast.Ident); ok {
                            typeName = ident.Name
                        }
                    case *ast.Ident:
                        // Value receiver
                        typeName = recvType.Name
                    }
                    methodName := x.Name.Name

                    // Count number of parameters and results
                    numParams := 0
                    if x.Type.Params != nil {
                        for _, param := range x.Type.Params.List {
                            numParams += len(param.Names)
                        }
                    }
                    numResults := 0
                    if x.Type.Results != nil {
                        for _, result := range x.Type.Results.List {
                            if result.Names != nil {
                                numResults += len(result.Names)
                            } else {
                                // Anonymous result (no name)
                                numResults++
                            }
                        }
                    }

                    if typeName != "" {
                        if _, exists := typeInfos[typeName]; !exists {
                            typeInfos[typeName] = &TypeInfo{
                                Name:    typeName,
                                Methods: make(map[string]*MethodInfo),
                            }
                        }
                        typeInfos[typeName].Methods[methodName] = &MethodInfo{
                            Name:    methodName,
                            Params:  numParams,
                            Results: numResults,
                        }
                    }
                }
            }
            return true
        })
    }
    return typeInfos, nil
}

func generateUnmarshalJSON(fileErrorTypes []string, receiverType string) (string, error) {
    tmpl := `func (e *{{.ReceiverType}}) UnmarshalJSON(bytes []byte) error {
    localType := struct {
        Type string {{printf "%cjson:\\\"type\\\"%c" '\u0060' '\u0060'}}
        Err  json.RawMessage {{printf "%cjson:\\\"error\\\"%c" '\u0060' '\u0060'}}
    }{}
    if err := json.Unmarshal(bytes, &localType); err != nil {
        return err
    }
    switch localType.Type {
    {{- range .FileErrorTypes}}
    case reflect.TypeOf(&{{.}}{}).String():
        var te {{.}}
        if unmarshallError := json.Unmarshal(localType.Err, &te); unmarshallError != nil {
            return unmarshallError
        }
        e.Err = &te
        e.Type = localType.Type
    {{- end}}
    default:
        return &UnknownStoreTypeError{TypeName: localType.Type}
    }
    return nil
}
`
    data := map[string]interface{}{
        "ReceiverType":   receiverType,
        "FileErrorTypes": fileErrorTypes,
    }

    t, err := template.New("unmarshalJSON").Parse(tmpl)
    if err != nil {
        return "", err
    }

    var buf bytes.Buffer
    err = t.Execute(&buf, data)
    if err != nil {
        return "", err
    }

    return buf.String(), nil
}

func insertOrReplaceMethod(fset *token.FileSet, file *ast.File, receiverType, methodName, generatedCode string) error {
    var methodFound bool
    var newDecls []ast.Decl

    // Parse the generated method code to get its AST node
    genFile, err := parser.ParseFile(token.NewFileSet(), "", generatedCode, parser.ParseComments)
    if err != nil {
        return fmt.Errorf("failed to parse generated code: %w", err)
    }
    var generatedMethod *ast.FuncDecl
    for _, decl := range genFile.Decls {
        if funcDecl, ok := decl.(*ast.FuncDecl); ok {
            if funcDecl.Name.Name == methodName {
                generatedMethod = funcDecl
                break
            }
        }
    }
    if generatedMethod == nil {
        return fmt.Errorf("generated method %s not found in parsed code", methodName)
    }

    // Iterate over declarations in the existing file
    for _, decl := range file.Decls {
        if funcDecl, ok := decl.(*ast.FuncDecl); ok {
            // Check if this is the method we want to replace
            if funcDecl.Name.Name == methodName && funcDecl.Recv != nil {
                recvType := ""
                switch recv := funcDecl.Recv.List[0].Type.(type) {
                case *ast.StarExpr:
                    if ident, ok := recv.X.(*ast.Ident); ok {
                        recvType = ident.Name
                    }
                case *ast.Ident:
                    recvType = recv.Name
                }
                if recvType == receiverType {
                    // Replace this method with the generated one
                    methodFound = true
                    newDecls = append(newDecls, generatedMethod)
                    continue // Skip adding the old method
                }
            }
        }
        newDecls = append(newDecls, decl)
    }
    if !methodFound {
        // Method not found; append the generated method
        newDecls = append(newDecls, generatedMethod)
    }

    // Update the file declarations
    file.Decls = newDecls
    return nil
}

func main() {
