```go
package main

import (
    "bytes"
    "flag"
    "fmt"
    "go/ast"
    "go/parser"
    "go/printer"
    "go/token"
    "io"
    "io/ioutil"
    "os"
    "path/filepath"
    "strings"
    "text/template"

    "golang.org/x/tools/go/packages"
)

type MethodInfo struct {
    Name         string
    Params       int
    Results      int
    PackageName  string
    PackagePath  string
    FullyQualify bool // Whether to use package name when referencing the type
}

type TypeInfo struct {
    Name         string
    PackageName  string
    PackagePath  string
    Methods      map[string]*MethodInfo
}

func collectTypesImplementingFileError(rootDir string) (map[string]*TypeInfo, error) {
    cfg := &packages.Config{
        Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes |
            packages.NeedTypesInfo | packages.NeedImports | packages.NeedDeps,
        Dir: rootDir,
    }

    pkgs, err := packages.Load(cfg, "./...")
    if err != nil {
        return nil, err
    }

    typeInfos := make(map[string]*TypeInfo)

    for _, pkg := range pkgs {
        for ident, obj := range pkg.TypesInfo.Defs {
            if obj == nil {
                continue
            }
            // Look for types (type declarations)
            if typeName, ok := obj.(*ast.TypeSpec); ok {
                name := typeName.Name.Name
                if _, exists := typeInfos[name]; !exists {
                    typeInfos[name] = &TypeInfo{
                        Name:        name,
                        PackageName: pkg.Name,
                        PackagePath: pkg.PkgPath,
                        Methods:     make(map[string]*MethodInfo),
                    }
                }
            }
        }

        // Collect method information
        for ident, obj := range pkg.TypesInfo.Defs {
            if obj == nil {
                continue
            }
            // Look for methods
            if funcDecl, ok := obj.(*ast.FuncDecl); ok && funcDecl.Recv != nil && len(funcDecl.Recv.List) > 0 {
                methodName := funcDecl.Name.Name
                receiver := funcDecl.Recv.List[0]
                var typeName string
                var fullyQualify bool

                // Get the type name of the receiver
                switch recvType := receiver.Type.(type) {
                case *ast.StarExpr:
                    // Pointer receiver
                    switch ident := recvType.X.(type) {
                    case *ast.Ident:
                        typeName = ident.Name
                    case *ast.SelectorExpr:
                        // Imported package type
                        pkgIdent, ok := ident.X.(*ast.Ident)
                        if ok {
                            typeName = ident.Sel.Name
                            fullyQualify = true
                        }
                    }
                case *ast.Ident:
                    // Value receiver
                    typeName = recvType.Name
                case *ast.SelectorExpr:
                    // Imported package type
                    pkgIdent, ok := recvType.X.(*ast.Ident)
                    if ok {
                        typeName = recvType.Sel.Name
                        fullyQualify = true
                    }
                }

                // Count number of parameters and results
                numParams := 0
                if funcDecl.Type.Params != nil {
                    for _, param := range funcDecl.Type.Params.List {
                        if len(param.Names) == 0 {
                            numParams++
                        } else {
                            numParams += len(param.Names)
                        }
                    }
                }
                numResults := 0
                if funcDecl.Type.Results != nil {
                    for _, result := range funcDecl.Type.Results.List {
                        if len(result.Names) == 0 {
                            numResults++
                        } else {
                            numResults += len(result.Names)
                        }
                    }
                }

                if typeName != "" {
                    if _, exists := typeInfos[typeName]; !exists {
                        typeInfos[typeName] = &TypeInfo{
                            Name:         typeName,
                            PackageName:  pkg.Name,
                            PackagePath:  pkg.PkgPath,
                            Methods:      make(map[string]*MethodInfo),
                        }
                    }
                    typeInfos[typeName].Methods[methodName] = &MethodInfo{
                        Name:         methodName,
                        Params:       numParams,
                        Results:      numResults,
                        PackageName:  pkg.Name,
                        PackagePath:  pkg.PkgPath,
                        FullyQualify: fullyQualify,
                    }
                }
            }
        }
    }

    return typeInfos, nil
}

func generateUnmarshalJSON(fileErrorTypes []*TypeInfo, receiverType string) (string, error) {
    tmpl := "func (e *{{.ReceiverType}}) UnmarshalJSON(bytes []byte) error {\n" +
        "    localType := struct {\n" +
        "        Type string `json:\"type\"`\n" +
        "        Err  json.RawMessage `json:\"error\"`\n" +
        "    }{}\n" +
        "    if err := json.Unmarshal(bytes, &localType); err != nil {\n" +
        "        return err\n" +
        "    }\n" +
        "    switch localType.Type {\n" +
        "{{- range .FileErrorTypes}}\n" +
        "    case reflect.TypeOf(&{{.QualifiedName}}{}).String():\n" +
        "        var te {{.QualifiedName}}\n" +
        "        if unmarshallError := json.Unmarshal(localType.Err, &te); unmarshallError != nil {\n" +
        "            return unmarshallError\n" +
        "        }\n" +
        "        e.Err = &te\n" +
        "        e.Type = localType.Type\n" +
        "{{- end}}\n" +
        "    default:\n" +
        "        return &UnknownStoreTypeError{TypeName: localType.Type}\n" +
        "    }\n" +
        "    return nil\n" +
        "}\n"

    // Prepare data for the template
    type TemplateTypeInfo struct {
        QualifiedName string // packageName.TypeName
    }

    var templateTypes []TemplateTypeInfo
    for _, typeInfo := range fileErrorTypes {
        qualifiedName := typeInfo.Name
        if typeInfo.PackageName != "" && typeInfo.PackageName != "main" {
            qualifiedName = fmt.Sprintf("%s.%s", typeInfo.PackageName, typeInfo.Name)
        }
        templateTypes = append(templateTypes, TemplateTypeInfo{
            QualifiedName: qualifiedName,
        })
    }

    data := map[string]interface{}{
        "ReceiverType":   receiverType,
        "FileErrorTypes": templateTypes,
    }

    t, err := template.New("unmarshalJSON").Parse(tmpl)
    if err != nil {
        return "", err
    }

    var buf bytes.Buffer
    err = t.Execute(&buf, data)
    if err != nil {
        return "", err
    }

    return buf.String(), nil
}

func insertOrReplaceMethod(fset *token.FileSet, file *ast.File, receiverType, methodName, generatedCode string) error {
    var methodFound bool
    var newDecls []ast.Decl

    // Parse the generated method code to get its AST node
    genFile, err := parser.ParseFile(token.NewFileSet(), "", generatedCode, parser.ParseComments)
    if err != nil {
        return fmt.Errorf("failed to parse generated code: %w", err)
    }
    var generatedMethod *ast.FuncDecl
    for _, decl := range genFile.Decls {
        if funcDecl, ok := decl.(*ast.FuncDecl); ok {
            if funcDecl.Name.Name == methodName {
                generatedMethod = funcDecl
                break
            }
        }
    }
    if generatedMethod == nil {
        return fmt.Errorf("generated method %s not found in parsed code", methodName)
    }

    // Iterate over declarations in the existing file
    for _, decl := range file.Decls {
        if funcDecl, ok := decl.(*ast.FuncDecl); ok {
            // Check if this is the method we want to replace
            if funcDecl.Name.Name == methodName && funcDecl.Recv != nil {
                recvType := ""
                switch recv := funcDecl.Recv.List[0].Type.(type) {
                case *ast.StarExpr:
                    if ident, ok := recv.X.(*ast.Ident); ok {
                        recvType = ident.Name
                    }
                case *ast.Ident:
                    recvType = recv.Name
                }
                if recvType == receiverType {
                    // Replace this method with the generated one
                    methodFound = true
                    newDecls = append(newDecls, generatedMethod)
                    continue // Skip adding the old method
                }
            }
        }
        newDecls = append(newDecls, decl)
    }
    if !methodFound {
        // Method not found; append the generated method
        newDecls = append(newDecls, generatedMethod)
    }

    // Update the file declarations
    file.Decls = newDecls
    return nil
}

func ensureImports(fset *token.FileSet, file *ast.File, imports map[string]string) {
    existingImports := make(map[string]string)
    for _, imp := range file.Imports {
        path := strings.Trim(imp.Path.Value, "\"")
        var name string
        if imp.Name != nil {
            name = imp.Name.Name
        } else {
            name = filepath.Base(path)
        }
        existingImports[path] = name
    }

    // Add missing imports
    for path, name := range imports {
        if _, exists := existingImports[path]; !exists {
            imp := &ast.ImportSpec{
                Path: &ast.BasicLit{
                    Kind:  token.STRING,
                    Value: fmt.Sprintf("\"%s\"", path),
                },
            }
            if name != "" && name != filepath.Base(path) {
                imp.Name = ast.NewIdent(name)
            }
            impDecl := &ast.GenDecl{
                Tok:   token.IMPORT,
                Specs: []ast.Spec{imp},
            }
            file.Decls = append([]ast.Decl{impDecl}, file.Decls...)
        }
    }
}

func main() {
    // Command-line flags
    var (
        rootDir      string
        targetFile   string
        receiverType string
    )
    flag.StringVar(&rootDir, "root", ".", "Root directory to search for Go files")
    flag.StringVar(&targetFile, "file", "", "Path to the Go file to modify")
    flag.StringVar(&receiverType, "receiver", "StoreType", "Receiver type name for UnmarshalJSON method")
    flag.Parse()

    if targetFile == "" {
        fmt.Println("Please specify the path to the Go file using -file flag.")
        os.Exit(1)
    }

    // Step 1: Collect types that implement FileError interface
    typeInfos, err := collectTypesImplementingFileError(rootDir)
    if err != nil {
        fmt.Printf("Error collecting types and methods: %v\n", err)
        return
    }

    // Identify types implementing FileError interface
    var fileErrorTypes []*TypeInfo
    for _, info := range typeInfos {
        if methodInfo, exists := info.Methods["IsFileError"]; exists {
            if methodInfo.Params == 0 && methodInfo.Results == 0 {
                // Method signature matches: no parameters, no results
                fileErrorTypes = append(fileErrorTypes, info)
            }
        }
    }

    // Step 2: Generate UnmarshalJSON method using text/template
    methodCode, err := generateUnmarshalJSON(fileErrorTypes, receiverType)
    if err != nil {
        fmt.Printf("Error generating UnmarshalJSON method: %v\n", err)
        return
    }

    // Step 3: Read and parse the target Go file
    fset := token.NewFileSet()
    src, err := ioutil.ReadFile(targetFile)
    if err != nil {
        fmt.Printf("Error reading target Go file: %v\n", err)
        return
    }
    fileAST, err := parser.ParseFile(fset, targetFile, src, parser.ParseComments)
    if err != nil {
        fmt.Printf("Error parsing target Go file: %v\n", err)
        return
    }

    // Step 4: Insert or replace UnmarshalJSON method in the AST
    err = insertOrReplaceMethod(fset, fileAST, receiverType, "UnmarshalJSON", methodCode)
    if err != nil {
        fmt.Printf("Error inserting/replacing method: %v\n", err)
        return
    }

    // Step 5: Ensure necessary imports are present
    importsNeeded := map[string]string{
        "encoding/json": "",
        "reflect":       "",
    }
    for _, typeInfo := range fileErrorTypes {
        if typeInfo.PackagePath != "" && typeInfo.PackageName != fileAST.Name.Name {
            importsNeeded[typeInfo.PackagePath] = typeInfo.PackageName
        }
    }
    ensureImports(fset, fileAST, importsNeeded)

    // Step 6: Write the modified AST back to the file
    var buf bytes.Buffer
    err = formatNode(&buf, fset, fileAST)
    if err != nil {
        fmt.Printf("Error formatting modified AST: %v\n", err)
        return
    }

    err = ioutil.WriteFile(targetFile, buf.Bytes(), 0644)
    if err != nil {
        fmt.Printf("Error writing modified Go file: %v\n", err)
        return
    }

    fmt.Println("Method successfully inserted/replaced in the target Go file.")
}

